{
  "loaded": [
    {
      "tool_id": "hirearchy::whoami",
      "description": "Your address, role, budget, direct reports, open tasks, outstanding delegations and charter.",
      "input_schema": {
        "type": "object",
        "properties": {}
      }
    },
    {
      "tool_id": "hirearchy::inbox",
      "description": "The messages for this run. For root (the human) this lists unread messages and marks them read.",
      "input_schema": {
        "type": "object",
        "properties": {}
      }
    },
    {
      "tool_id": "hirearchy::delegate",
      "description": "Assign a task to one of your direct reports.\n\n        to: the report's address (e.g. \"ceo/cto\"). title: a few words. goal: what outcome is needed and why.\n        acceptance: concrete, checkable criteria for \"done\". inputs: paths (relative to the org root) the\n        report should read. budget: runs handed to the report from your own budget. If you omit it, the default is\n        min(default_budget from ORG.md, your budget - reserve), where the reserve keeps one run per outstanding\n        delegation plus one for this one; if that is below 1 the call fails and tells you your options.\n        An explicit budget must leave that same reserve.\n        Copy the relevant acceptance criteria verbatim from the task you are working on; never paraphrase or relax them.\n        revises: when sending work back for rework, the id of the earlier task you sent to the same report.\n        A service request is sent back with request(..., revises=...).\n        source (with revises): \"human\" when the user asked for this rework\n        (a rework after their own rejection, carrying their corrections, is one), \"relayed\" (the default) when it is your\n        own reading; the owner sees which.\n        Returns the task id. Do not wait for the result: end your run, the result will wake you.\n        ",
      "input_schema": {
        "type": "object",
        "properties": {
          "to": {
            "title": "To",
            "type": "string"
          },
          "title": {
            "title": "Title",
            "type": "string"
          },
          "goal": {
            "title": "Goal",
            "type": "string"
          },
          "acceptance": {
            "title": "Acceptance",
            "type": "string"
          },
          "inputs": {
            "anyOf": [
              {
                "items": {
                  "type": "string"
                },
                "type": "array"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Inputs"
          },
          "budget": {
            "anyOf": [
              {
                "type": "integer"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Budget"
          },
          "revises": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Revises"
          },
          "source": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Source"
          }
        },
        "required": [
          "to",
          "title",
          "goal",
          "acceptance"
        ]
      }
    },
    {
      "tool_id": "hirearchy::report",
      "description": "Answer a task assigned to you. Goes to whoever assigned it.\n\n        status: \"done\" (every acceptance criterion verifiably met), \"failed\", or \"blocked\" (say what would unblock it).\n        `done` and `failed` are final: a second report is refused. `blocked` is not: once the blocker is resolved\n        you may report the task again, once per blocked report (any status; the new report supersedes the old one),\n        under the same rules. A `send` note never changes a task's outcome and must not claim criteria are met.\n        summary: at most ~10 lines; this is all your manager reads by default. artifacts: paths of the\n        files that hold the work; they must exist. Files in the organization: path relative to the org root.\n        Files in your workspace: the ABSOLUTE path (anything else outside the organization is refused). The runtime\n        annotates each with its word count and whether it changed since the task was assigned.\n        lessons: required when the task is a request for a service, whatever the status - done, failed or blocked\n        (1-3 lines, at most 800 characters: what worked or went wrong, what to change in the playbook, the evidence:\n        runs, rework, review findings); it is recorded in the result and reviewed before the next request. Optional\n        otherwise.\n        ",
      "input_schema": {
        "type": "object",
        "properties": {
          "task_id": {
            "title": "Task Id",
            "type": "string"
          },
          "status": {
            "title": "Status",
            "type": "string"
          },
          "summary": {
            "title": "Summary",
            "type": "string"
          },
          "artifacts": {
            "anyOf": [
              {
                "items": {
                  "type": "string"
                },
                "type": "array"
              },
              {
