              }
            ],
            "default": null,
            "title": "Source"
          },
          "base": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Base"
          }
        },
        "required": [
          "service"
        ]
      }
    },
    {
